-- Migration 000109: extend plastic materials to higher ink runs
--
-- Plasma is extending the three plastic letterpress materials to
-- support more ink runs. Same fixed-delta rule as migrations 000107
-- and 000108 (which extended paper letterpress and paper letterpress
-- with gilding to 5/6 then 7/8 ink):
--
--   p_n = p4 + (n - 4) * (p4 - p3) = (n - 3) * p4 - (n - 4) * p3
--
-- Per-material targets:
--
--   plastic_translucent : 5_ink, 6_ink
--   plastic_tinted      : 5_ink, 6_ink
--   plastic_satin       : 5_ink, 6_ink, 7_ink, 8_ink
--
-- Variant rows: no schema changes. All three plastics already carry
-- 5_ink through 8_ink as placeholder variants from migration 000079
-- (which cross-product back-filled higher-ink variants for every
-- material that had ink_count variants seeded). Until this migration
-- runs, those placeholders route through the form's custom-quote path
-- (zero price_tiers means custom quote). Once this migration applies,
-- standard pricing renders automatically; no frontend changes needed.
--
-- Shape of this migration:
--
--   1. Insert 4728 price_tier rows generated by
--      scripts/generate_000109_tiers.py from the canonical 3_ink and
--      4_ink rows in seed.sql. Plastics never had any data-gap
--      fix-ups (unlike letterpress, which needed 000098, 000105,
--      000106), so the generator reads a single source file.
--
--      Per-material row counts (197 quantities x 3 currencies x ink count):
--        plastic_translucent : 2 inks x 591 = 1182 rows
--        plastic_tinted      : 2 inks x 591 = 1182 rows
--        plastic_satin       : 4 inks x 591 = 2364 rows
--        total                              = 4728 rows
--
-- Idempotency: ON CONFLICT DO NOTHING on
-- (material_variant_id, currency, quantity). Re-applying this
-- migration is a no-op once the rows exist. Mirrors the 000107 and
-- 000108 patterns.
--
-- Two properties of the source data worth recording for future-us:
--
-- 1. Tinted GBP carries roughly twice the (p4 - p3) delta of
--    translucent and satin GBP at most quantities. The extrapolated
--    tinted GBP 5/6 ink prices look bigger than EUR/USD as a result
--    (e.g. tinted 6_ink GBP q5000 = £3927). This is faithful to the
--    rule and commercially consistent: GBP prices include 20% UK
--    VAT (EUR and USD do not). £3927 ex-VAT is roughly £3273, which
--    sits cleanly between the EUR (€2820) and USD ($3699) figures.
--
-- 2. plastic_translucent and plastic_satin share IDENTICAL prices in
--    EUR and USD across all 197 quantities for inks 1-4 (a property
--    of the upstream seed data). The linear-extrapolation rule
--    preserves that identity, so the new 5/6 ink rows for
--    translucent and the new 5/6 ink rows for satin will also be
--    identical in EUR and USD. Not introduced by this migration.
--    They diverge in GBP at the high end (q2500 onwards) per the
--    underlying seed.
--
-- Recon verification noted before generating: zero monotonicity
-- violations across all 4728 projected rows (better than the 10
-- £1 dips that 000108 produced on plain EUR 8_ink letterpress).
-- The non-monotonic USD delta progression in the q1000-q3000 range
-- doesn't translate into ladder dips because the absolute p4 growth
-- between consecutive quantities exceeds the delta wobbles. No
-- monotonicity smoothing needed.

begin;

insert into price_tiers (material_variant_id, currency, quantity, total_price, unit_price)
select mv.id, t.currency, t.quantity, t.total_price, t.unit_price
from materials m
join material_variants mv on mv.material_id = m.id
join (values
